window.S17Page={"sceneId":"r5","caseId":"s17x-r5-quality-softsensor","name":"产品质量在线软测量","title":"产品质量在线软测量：化验到来之前","summary":"炼油过程的温度、压力和流量测得频繁，产品化验却需要等待。把过程量与取样物料对齐，拟合岭回归密度软测量，再与最近已到达的化验保持值、历史均值进行同点对照。","directory":"expansion-cases","caseVersion":"1.0.1","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){
'use strict';
const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
function random(seed){let s=seed>>>0;return()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296;};}
function solve(A,b){const n=b.length,M=A.map((r,i)=>r.slice().concat(b[i]));for(let k=0;k<n;k++){let p=k;for(let i=k+1;i<n;i++)if(Math.abs(M[i][k])>Math.abs(M[p][k]))p=i;[M[p],M[k]]=[M[k],M[p]];const d=M[k][k];if(Math.abs(d)<1e-12)throw Error('拟合矩阵不可解');for(let j=k;j<=n;j++)M[k][j]/=d;for(let i=0;i<n;i++)if(i!==k){const f=M[i][k];for(let j=k;j<=n;j++)M[i][j]-=f*M[k][j];}}return M.map(r=>r[n]);}
const features=r=>[r.temperature,r.pressure,r.flow,r.reflux];
function generate(params={}){const cfg={seed:1705,delay:15,scenario:'normal',alignment:true,...params},groups=[],reference=[],labs=[];for(let k=0;k<21;k++){const split=k<12?'train':k<16?'validation':'test',rng=random(cfg.seed+k*7817),underlying=[],rows=[],regime=k%3;for(let i=0;i<42;i++){const temp=326+8*Math.sin(i/8+k*.6)+4*(regime-1)+(i>=22?7:0),pressure=2.35+.09*Math.cos(i/7+k)+.06*(regime-1),flow=96+5*Math.sin(i/11+k*.3)+3*(regime-1),reflux=2.6+.2*Math.cos(i/9+k);underlying.push({temperature:temp,pressure,flow,reflux});rows.push({group:'BATCH-'+String(k+1).padStart(2,'0'),minute:k*60+i,localMinute:i,regime:['低负荷','中负荷','高负荷'][regime],temperature:temp+(rng()-.5)*.5+(split==='test'&&cfg.scenario==='drift'?6:0),pressure:pressure+(rng()-.5)*.01,flow:flow+(rng()-.5)*.3,reflux:reflux+(rng()-.5)*.02});}
for(let i=6;i<42;i++){const x=underlying[i-3],density=820-.24*(x.temperature-326)+2.8*(x.pressure-2.35)+.14*(x.flow-96)-1.6*(x.reflux-2.6)+.006*(x.temperature-326)**2+.3*Math.sin(k*1.7)+(rng()-.5)*.65+(split==='test'&&cfg.scenario==='feed'?4.5:0);reference.push({group:rows[i].group,minute:rows[i].minute,localMinute:i,density,regime:rows[i].regime,split});if(i%5===1)labs.push({group:rows[i].group,sampleMinute:rows[i].minute,releaseMinute:rows[i].minute+cfg.delay,density,split});}
groups.push({id:rows[0].group,split,rows});}return {version:'r5-synthetic-1.0',dataNature:'教学合成；密度单位 kg/m³，范围由本例生成器设定',groups,labObservations:labs,evaluationTruth:reference,config:cfg};}
function alignedRow(groups,point,lag=3){const group=groups.find(g=>g.id===point.group);return group.rows[Math.max(0,point.localMinute-lag)];}
function trainingPairs(groups,labs){return labs.map(l=>{const point={group:l.group,localMinute:l.sampleMinute-groups.find(g=>g.id===l.group).rows[0].minute};return {x:features(alignedRow(groups,point,3)),y:l.density,group:l.group};});}
function fit(pairs,lambda=1){const mu=pairs[0].x.map((_,j)=>mean(pairs.map(p=>p.x[j]))),scale=mu.map((m,j)=>Math.max(1e-6,Math.sqrt(mean(pairs.map(p=>(p.x[j]-m)**2))))),Z=pairs.map(p=>[1,...p.x.map((v,j)=>(v-mu[j])/scale[j])]),n=5,A=Array.from({length:n},(_,j)=>Array.from({length:n},(_,l)=>Z.reduce((s,z)=>s+z[j]*z[l],0)+(j===l&&j?lambda:0))),b=Z[0].map((_,j)=>Z.reduce((s,z,i)=>s+z[j]*pairs[i].y,0));return {mu,scale,coeff:solve(A,b),lambda,trainMean:mean(pairs.map(p=>p.y)),trainN:pairs.length};}
function predictOne(x,model){return [1,...x.map((v,j)=>(v-model.mu[j])/model.scale[j])].reduce((s,v,j)=>s+v*model.coeff[j],0);}
// Only online process rows and already released laboratory observations enter inference.
function infer(groups,labObservations,model,params={}){const out=[];for(const group of groups)for(const row of group.rows.filter(r=>r.localMinute>=6)){const source=group.rows[row.localMinute-(params.alignment===false?0:3)],x=features(source),available=labObservations.filter(l=>l.releaseMinute<=row.minute&&l.sampleMinute<row.minute).sort((a,b)=>b.sampleMinute-a.sampleMinute),latest=available[0]??null,z=x.map((v,j)=>(v-model.mu[j])/model.scale[j]);out.push({group:row.group,minute:row.minute,localMinute:row.localMinute,regime:row.regime,x,sourceMinute:source.minute,predictedDensity:predictOne(x,model),lastLab:latest?latest.density:model.trainMean,lastLabSample:latest?latest.sampleMinute:null,lastLabRelease:latest?latest.releaseMinute:null,baselineFallback:!latest,trainMean:model.trainMean,outOfRange:z.some(v=>Math.abs(v)>3),maxStandardDistance:Math.max(...z.map(Math.abs))});}return out;}
function evaluate(predictions,evaluationTruth,key='predictedDensity'){const map=new Map(evaluationTruth.map(t=>[t.group+'/'+t.minute,t])),pairs=predictions.flatMap(p=>{const t=map.get(p.group+'/'+p.minute);return t?[{group:p.group,minute:p.minute,regime:t.regime,actual:t.density,predicted:p[key],error:p[key]-t.density}]:[];}),summarize=a=>({n:a.length,mae:a.length?mean(a.map(p=>Math.abs(p.error))):null,rmse:a.length?Math.sqrt(mean(a.map(p=>p.error*p.error))):null,bias:a.length?mean(a.map(p=>p.error)):null});return {...summarize(pairs),byRegime:['低负荷','中负荷','高负荷'].map(regime=>({regime,...summarize(pairs.filter(p=>p.regime===regime))})),pairs};}
function run(params={}){const data=generate(params),train=data.groups.filter(g=>g.split==='train'),validation=data.groups.filter(g=>g.split==='validation'),test=data.groups.filter(g=>g.split==='test'),modelAsOf=test[0].rows[6].minute,trainLabs=data.labObservations.filter(l=>l.split==='train'&&l.releaseMinute<=modelAsOf),validationLabs=data.labObservations.filter(l=>l.split==='validation'&&l.releaseMinute<=modelAsOf),pairs=trainingPairs(train,trainLabs),valPairs=trainingPairs(validation,validationLabs);let selection=null;for(const lambda of [.01,.1,1,10,100]){const model=fit(pairs,lambda),rmse=Math.sqrt(mean(valPairs.map(p=>(predictOne(p.x,model)-p.y)**2)));if(!selection||rmse<selection.rmse)selection={lambda,rmse,validationN:valPairs.length};}const model=fit(pairs,selection.lambda),prediction=infer(test,data.labObservations,model,data.config),evaluationTruth=data.evaluationTruth.filter(t=>t.split==='test'),metrics={model:evaluate(prediction,evaluationTruth),baseline:evaluate(prediction,evaluationTruth,'lastLab'),mean:evaluate(prediction,evaluationTruth,'trainMean')};return {sceneId:'r5',caseId:'s17x-r5-quality-softsensor',dataVersion:data.version,dataNature:data.dataNature,params:data.config,split:{train:train.map(g=>g.id),validation:validation.map(g=>g.id),test:test.map(g=>g.id),modelAsOf,trainLabels:pairs.length,validationLabels:valPairs.length,unavailableValidationLabels:data.labObservations.filter(l=>l.split==='validation'&&l.releaseMinute>modelAsOf).length,testRows:prediction.length},model,selection,prediction,evaluationTruth,labObservations:data.labObservations.filter(l=>l.split==='test'),metrics,availability:{futureFeatureCount:prediction.filter(p=>p.sourceMinute>p.minute).length,futureLabCount:prediction.filter(p=>p.lastLabRelease!=null&&p.lastLabRelease>p.minute).length,outOfRangeCount:prediction.filter(p=>p.outOfRange).length}};}
g.R5Core={mean,random,generate,alignedRow,trainingPairs,fit,predictOne,infer,evaluate,run};
})(globalThis);

